// Values holds every HERO9 setting decoded from the camera state.
// Settings the spec does not document for this model are kept in Unknown.
type Values struct {
	VideoResolution        VideoResolution        `json:"video-resolution" yaml:"video-resolution"`
	FramesPerSecond        FramesPerSecond        `json:"frames-per-second" yaml:"frames-per-second"`
	VideoTimelapseRate     VideoTimelapseRate     `json:"video-timelapse-rate" yaml:"video-timelapse-rate"`
	PhotoTimelapseRate     PhotoTimelapseRate     `json:"photo-timelapse-rate" yaml:"photo-timelapse-rate"`
	NightlapseRate         NightlapseRate         `json:"nightlapse-rate" yaml:"nightlapse-rate"`
	WebcamDigitalLenses    WebcamDigitalLenses    `json:"webcam-digital-lenses" yaml:"webcam-digital-lenses"`
	AutoPowerDown          AutoPowerDown          `json:"auto-power-down" yaml:"auto-power-down"`
	GPS                    GPS                    `json:"gps" yaml:"gps"`
	LCDBrightness          LCDBrightness          `json:"lcd-brightness" yaml:"lcd-brightness"`
	LED                    LED                    `json:"led" yaml:"led"`
	VideoLens              VideoLens              `json:"video-lens" yaml:"video-lens"`
	PhotoLens              PhotoLens              `json:"photo-lens" yaml:"photo-lens"`
	TimeLapseDigitalLenses TimeLapseDigitalLenses `json:"time-lapse-digital-lenses" yaml:"time-lapse-digital-lenses"`
	PhotoOutput            PhotoOutput            `json:"photo-output" yaml:"photo-output"`
	MediaFormat            MediaFormat            `json:"media-format" yaml:"media-format"`
	AntiFlicker            AntiFlicker            `json:"anti-flicker" yaml:"anti-flicker"`
	Hypersmooth            Hypersmooth            `json:"hypersmooth" yaml:"hypersmooth"`
	VideoDuration          VideoDuration          `json:"video-duration" yaml:"video-duration"`
	MultiShotDuration      MultiShotDuration      `json:"multi-shot-duration" yaml:"multi-shot-duration"`
	MaxLens                MaxLens                `json:"max-lens" yaml:"max-lens"`
	HindSight              HindSight              `json:"hindsight" yaml:"hindsight"`
	ScheduledCapture       ScheduledCapture       `json:"scheduled-capture" yaml:"scheduled-capture"`
	Unknown                map[SettingID]int64    `json:"unknown,omitempty" yaml:"unknown,omitempty"`
}

// apply stores one raw setting value into the typed field, or Unknown.
func (v *Values) apply(id SettingID, raw int64) {
	switch id {
	case SettingVideoResolution:
		v.VideoResolution = VideoResolution(raw)
	case SettingFramesPerSecond:
		v.FramesPerSecond = FramesPerSecond(raw)
	case SettingVideoTimelapseRate:
		v.VideoTimelapseRate = VideoTimelapseRate(raw)
	case SettingPhotoTimelapseRate:
		v.PhotoTimelapseRate = PhotoTimelapseRate(raw)
	case SettingNightlapseRate:
		v.NightlapseRate = NightlapseRate(raw)
	case SettingWebcamDigitalLenses:
		v.WebcamDigitalLenses = WebcamDigitalLenses(raw)
	case SettingAutoPowerDown:
		v.AutoPowerDown = AutoPowerDown(raw)
	case SettingGPS:
		v.GPS = GPS(raw)
	case SettingLCDBrightness:
		v.LCDBrightness = LCDBrightness(raw)
	case SettingLED:
		v.LED = LED(raw)
	case SettingVideoLens:
		v.VideoLens = VideoLens(raw)
	case SettingPhotoLens:
		v.PhotoLens = PhotoLens(raw)
	case SettingTimeLapseDigitalLenses:
		v.TimeLapseDigitalLenses = TimeLapseDigitalLenses(raw)
	case SettingPhotoOutput:
		v.PhotoOutput = PhotoOutput(raw)
	case SettingMediaFormat:
		v.MediaFormat = MediaFormat(raw)
	case SettingAntiFlicker:
		v.AntiFlicker = AntiFlicker(raw)
	case SettingHypersmooth:
		v.Hypersmooth = Hypersmooth(raw)
	case SettingVideoDuration:
		v.VideoDuration = VideoDuration(raw)
	case SettingMultiShotDuration:
		v.MultiShotDuration = MultiShotDuration(raw)
	case SettingMaxLens:
		v.MaxLens = MaxLens(raw)
	case SettingHindSight:
		v.HindSight = HindSight(raw)
	case SettingScheduledCapture:
		v.ScheduledCapture = ScheduledCapture(raw)
	default:
		if v.Unknown == nil {
			v.Unknown = map[SettingID]int64{}
		}
		v.Unknown[id] = raw
	}
}

